script:
country_event = {
	id = timeline.4
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		is_country_type = default
		fromfrom = {
			any_attacker = {
			is_same_value = root
			is_war_leader = yes
			}
		}
	}

	immediate = {
		fromfrom = {
			random_defender = {
				save_event_target_as = this_country_defender
			}
			random_attacker = {
				limit = {
					is_same_value = root
					is_war_leader = yes
				}
				save_event_target_as = this_country_attacker
